class Solution {
public:
    int videoStitching(vector<vector<int>>& clips, int time) {
        sort(clips.begin(), clips.end());
        int n = (int)clips.size();
        int count = 0;
        int covered = 0;
        int i = 0;
        while (covered < time) {
            int best = covered;
            while (i < n && clips[i][0] <= covered) {
                if (clips[i][1] > best) best = clips[i][1];
                i++;
            }
            if (best == covered) return -1;
            covered = best;
            count++;
        }
        return count;
    }
};
